package org.springframework.samples.petclinic.rest.function.owner;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.RequiredFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Rejects a create request that is missing or blank in any required owner field,
 * before {@link BuildOwner} runs. The names of the offending fields are reported
 * as a 400 by {@link org.springframework.samples.petclinic.rest.escalation.RequiredFieldsExceptionHandler}.
 *
 * <p>This is a manual guard rather than {@code @Valid} so that a missing or blank
 * required field yields the {@code errors} field-name array this endpoint promises,
 * instead of the generic schema-validation problem detail.
 */
public class RequireOwnerFields {

    /** A pragmatic syntactic email check: a local part, an '@', and a dotted domain,
     *  none containing whitespace or a second '@'. */
    private static final Pattern EMAIL_PATTERN =
            Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws RequiredFieldsException {
        List<String> errors = new ArrayList<>();
        checkField("firstName", request.getFirstName(), errors);
        checkField("lastName", request.getLastName(), errors);
        // Normalize the address before the required-field check, so an address that is
        // blank after normalization is rejected and the stored/returned value is canonical.
        String address = AddressNormalizer.normalize(request.getAddress());
        if (address.isEmpty()) {
            errors.add("address");
        }
        else {
            request.setAddress(address);
        }
        checkField("city", request.getCity(), errors);
        checkField("telephone", request.getTelephone(), errors);
        if (!errors.isEmpty()) {
            throw new RequiredFieldsException(errors);
        }
        // Normalize the telephone to E.164 form; reject when it cannot form a valid one.
        String telephone = Telephones.toE164(request.getTelephone());
        if (telephone == null) {
            throw new RequiredFieldsException(List.of("telephone"));
        }
        request.setTelephone(telephone);
        // Email is optional; when present it must be syntactically valid and is
        // stored and returned lower-cased.
        String email = request.getEmail();
        if (email != null && !email.isBlank()) {
            if (!EMAIL_PATTERN.matcher(email).matches()) {
                throw new RequiredFieldsException(List.of("email"));
            }
            request.setEmail(email.toLowerCase());
        }
        // Postcode is optional; when present it must be a 4-digit code that is valid for
        // the owner's city per the fixed region ranges (a city with no known region accepts
        // any 4-digit code). Validated here only when supplied, so a request without a
        // postcode stays accepted.
        if (!Postcodes.isValid(request.getPostcode(), request.getCity())) {
            throw new RequiredFieldsException(List.of("postcode"));
        }
        validated.set(request);
    }

    private static void checkField(String name, String value, List<String> errors) {
        if (value == null || value.isBlank()) {
            errors.add(name);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * Rejects a create request that would join an existing household without declaring it.
 * The household is keyed on (lastName, postcode) via {@link Households}, so an incoming
 * owner whose derived {@code householdId} already belongs to an existing owner is a
 * household duplicate, reported as a 409 by
 * {@link org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityExceptionHandler}.
 *
 * <p>Setting {@code sharesHousehold} bypasses this block: the owner is then created as a
 * declared household member (and, being declared, is not flagged as a possible duplicate by
 * {@link AssignPossibleDuplicate}). Owners in different households always derive a different
 * {@code householdId}, so they never collide here.
 */
public class RequireUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateIdentityException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // a declared household member bypasses the duplicate block
        }
        String householdId = Households.idFor(request.getLastName(), request.getPostcode());
        for (Owner existing : ownerRepository.findAll()) {
            if (householdId.equals(existing.getHouseholdId())) {
                throw new DuplicateIdentityException(householdId);
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

/**
 * Rejects a create request whose supplied {@code registrationDate} is later than the
 * server's current date, before {@link BuildOwner} runs. Reported as a 400 by
 * {@link org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateExceptionHandler}.
 *
 * <p>A request that omits the date is left for {@link BuildOwner} to default to the
 * server date, so no guard is needed there.
 */
public class RequireNotFutureRegistrationDate {

    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
        LocalDate supplied = request.getRegistrationDate();
        LocalDate today = LocalDate.now();
        if (supplied != null && supplied.isAfter(today)) {
            throw new FutureRegistrationDateException(supplied, today);
        }
    }
}

